// Clean Architecture dependency direction -- Domain has ZERO external dependencies
namespace OrdersApi.Domain
{
    public class Order   // pure business entity, no EF Core attributes, no framework references
    {
        public int Id { get; private set; }
        public decimal Amount { get; private set; }
        public OrderStatus Status { get; private set; }

        public void Approve()
        {
            if (Status != OrderStatus.Pending)
                throw new InvalidOperationException("Only pending orders can be approved");
            Status = OrderStatus.Approved;
        }
    }
}

// Application layer -- defines the INTERFACE, depends only on Domain
namespace OrdersApi.Application
{
    public interface IOrderRepository
    {
        Task<Order> GetByIdAsync(int id);
        Task SaveAsync(Order order);
    }

    // MediatR-style command handler -- one class per use case
    public class ApproveOrderCommand : IRequest { public int OrderId { get; set; } }

    public class ApproveOrderHandler : IRequestHandler<ApproveOrderCommand>
    {
        private readonly IOrderRepository _repo;
        private readonly IMediator _mediator;

        public ApproveOrderHandler(IOrderRepository repo, IMediator mediator)
        {
            _repo = repo; _mediator = mediator;
        }

        public async Task Handle(ApproveOrderCommand request, CancellationToken ct)
        {
            var order = await _repo.GetByIdAsync(request.OrderId);
            order.Approve();
            await _repo.SaveAsync(order);
            await _mediator.Publish(new OrderApprovedEvent(order.Id), ct);  // decoupled side effects
        }
    }
}

// Infrastructure layer -- IMPLEMENTS the interface, depends on Application/Domain, uses EF Core
namespace OrdersApi.Infrastructure
{
    public class EfOrderRepository : IOrderRepository
    {
        private readonly AppDbContext _context;
        public EfOrderRepository(AppDbContext context) => _context = context;

        public Task<Order> GetByIdAsync(int id) => _context.Orders.FindAsync(id).AsTask();
        public Task SaveAsync(Order order) => _context.SaveChangesAsync();
    }
}

